// Client-side access to the prebuilt building data in public/data/
// (generated by `npm run data`; see scripts/). Searches run locally: no API calls.

export const RADIUS_M = 400;

export function haversine(lat1, lng1, lat2, lng2) {
  const k = Math.PI / 180;
  const dLat = (lat2 - lat1) * k;
  const dLng = (lng2 - lng1) * k;
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(lat1 * k) * Math.cos(lat2 * k) * Math.sin(dLng / 2) ** 2;
  return 2 * 6371000 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

const CHRS_MEANING = {
  Red: 'Red: potentially significant to Chicago, Illinois, or the nation',
  Orange: 'Orange: potentially significant to the surrounding community',
};

const NR_LABEL = {
  NHL: 'National Historic Landmark',
  NR: 'Listed on the National Register of Historic Places',
};

async function getJson(path) {
  const res = await fetch(path);
  if (!res.ok) throw new Error(`Couldn't load ${path} (HTTP ${res.status})`);
  return res.json();
}

function memo(fn) {
  let p;
  return () =>
    (p ??= fn().catch((err) => {
      p = undefined; // allow retry after a failure
      throw err;
    }));
}

const loadBuildings = memo(() => getJson('/data/buildings.json'));
const loadStyles = memo(() => getJson('/data/styles.json'));
const loadLandmarkDetails = memo(() => getJson('/data/landmark-details.json').then((d) => d.landmarks));

/** Start downloading everything in the background (e.g. on page load). */
export function preload() {
  loadBuildings().catch(() => {});
  loadStyles().catch(() => {});
  loadLandmarkDetails().catch(() => {});
}

function expand(raw, data, styles) {
  const styleNames = (raw.s ?? []).map((i) => data.styles[i]).filter(Boolean);
  return {
    key: raw.k,
    lat: raw.la,
    lng: raw.lo,
    name: raw.n ?? null,
    historicName: raw.h ?? null,
    address: raw.a ?? null,
    yearBuilt: raw.y ?? null,
    architect: raw.ar ?? null,
    styles: styleNames.map((s) => {
      const guide = styles.guide[styles.chrsToGuide[s]] ?? null;
      return { name: guide?.name ?? s.charAt(0) + s.slice(1).toLowerCase(), guide };
    }),
    type: raw.t === undefined ? null : data.types[raw.t] ?? null,
    chrsColor: raw.c ?? null,
    chrsMeaning: raw.c ? CHRS_MEANING[raw.c] ?? raw.c : null,
    landmarkId: raw.l ?? null,
    landmarkDate: raw.ld ?? null,
    nationalRegister: raw.nr ? NR_LABEL[raw.nr] : null,
  };
}

/**
 * Buildings within `radius` metres, nearest first, plus nearby historic districts.
 * @returns {Promise<{ buildings: object[], districts: object[], generated: string }>}
 */
export async function getNearby(lat, lng, radius = RADIUS_M) {
  const [data, styles] = await Promise.all([loadBuildings(), loadStyles()]);

  // Cheap bounding-box prefilter before the exact distance
  const dLat = radius / 111_320;
  const dLng = radius / (111_320 * Math.cos((lat * Math.PI) / 180));
  const buildings = [];
  for (const raw of data.buildings) {
    if (Math.abs(raw.la - lat) > dLat || Math.abs(raw.lo - lng) > dLng) continue;
    const distance = haversine(lat, lng, raw.la, raw.lo);
    if (distance <= radius) buildings.push({ ...expand(raw, data, styles), distance });
  }
  buildings.sort((a, b) => a.distance - b.distance);

  const districts = data.districts
    .filter(({ b: [minLat, minLng, maxLat, maxLng] }) => lat >= minLat - dLat && lat <= maxLat + dLat && lng >= minLng - dLng && lng <= maxLng + dLng)
    .map((d) => ({ name: d.n, label: NR_LABEL[d.nr] }));

  return { buildings, districts, generated: data.generated };
}

/**
 * Official description, photo, "more information" links, full "year built" text,
 * and any styles the City's page links to, for a Chicago Landmark.
 */
export async function getLandmarkDetails(landmarkId) {
  if (!landmarkId) return null;
  const [all, styles] = await Promise.all([loadLandmarkDetails(), loadStyles()]);
  const d = all[landmarkId];
  if (!d) return null;
  return {
    ...d,
    styles: (d.styleIds ?? [])
      .map((id) => styles.guide[id])
      .filter(Boolean)
      .map((guide) => ({ name: guide.name, guide })),
  };
}

/** Facts sent to the narrative endpoint (verified fields only). */
export function narrativeFacts(b) {
  return {
    name: b.name ?? undefined,
    historicName: b.historicName ?? undefined,
    address: b.address ?? undefined,
    year: b.yearBuilt ?? undefined,
    architect: b.architect ?? undefined,
    type: b.type ?? undefined,
    styles: b.styles.map((s) => s.name).join(', ') || undefined,
    styleSummary: b.styles[0]?.guide?.summary ?? undefined,
    landmarkDate: b.landmarkDate ?? undefined,
    chrsRating: b.chrsMeaning ?? undefined,
    nationalRegister: b.nationalRegister ?? undefined,
  };
}

/** Title for a building card: its name, else its address. */
export const displayName = (b) => b.name || b.address || 'Unnamed building';
